for fqn, body in S.items():
    pkg, name = fqn.rsplit('.', 1)
    d = os.path.join('stubs', *pkg.split('.'))
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, name + '.java'), 'w') as f:
        f.write(f'package {pkg};\n{body}\n')
print(len(S), 'stubs')
